//! Golden-file regression tests for asperitas-cli DSP processors.
//!
//! Every case goes through [`asperitas_cli::process::run_process`], the entry point the CLI
//! binary calls, so the goldens cover argument parsing, the parameter tables, WAV reading and
//! widening, the processor, and WAV writing together. Two kinds of input feed the same
//! comparison: deterministic signals generated by `synth` (written to a temporary WAV first),
//! and the recorded instrument clips in `audio/instruments/`. Output is frozen as a listenable
//! 32-bit float WAV under `audio/goldens/`, named `{processor}_{variant}_{input}.wav`.
//!
//! Float storage and a near-bit-exact bound mean a change anywhere in the output is visible,
//! including a quiet filter tail far below what 16-bit quantisation could resolve. The
//! `gain` processor at its default 0 dB is an identity, so only one synthetic input carries a
//! default-parameter gain golden; the other gain cases use non-default gains.
//!
//! Set `UPDATE_GOLDENS=1` to regenerate goldens. This is deliberately explicit: a
//! golden diff means "listen to this before accepting it", not "run the update
//! command". That distinction is the whole value of the mechanism.

use asperitas_cli::process::{run_process, ProcessArgs};
use asperitas_cli::synth;
use asperitas_cli::wav_io;
use asperitas_dsp::processor::Frame;

const GOLDEN_DIR: &str = concat!(env!("CARGO_MANIFEST_DIR"), "/../../audio/goldens");
const CORPUS_DIR: &str = concat!(env!("CARGO_MANIFEST_DIR"), "/../../audio/instruments");
const SAMPLE_RATE: u32 = 48000;
const DURATION: f32 = 1.0;

/// Tolerance for per-sample comparison (absolute delta).
///
/// Goldens are stored as 32-bit float, so the only legitimate difference is last-bit
/// float-arithmetic variation between platforms; the synth uses libm to keep its own
/// signals reproducible. Anything audible, or any real change to the DSP, is far larger.
const TOLERANCE: f32 = 1e-6;

/// Where a golden case's input comes from.
enum Input {
    /// A signal generated by `synth` at [`SAMPLE_RATE`] for [`DURATION`].
    Synthetic(&'static str),
    /// A recorded instrument clip, by file stem in `audio/instruments/`.
    Clip(&'static str),
}

impl Input {
    fn slug(&self) -> &'static str {
        match self {
            Input::Synthetic(s) | Input::Clip(s) => s,
        }
    }

    /// Path of a WAV file holding this input. Synthetic signals are written into `dir`;
    /// clips are used in place. Clips keep their own sample rate, so this exercises the
    /// same rate handling the CLI applies to arbitrary user files.
    fn path(&self, dir: &std::path::Path) -> String {
        match self {
            Input::Synthetic(kind) => {
                let mono = match *kind {
                    "impulse" => synth::generate_impulse(SAMPLE_RATE, DURATION),
                    "sweep" => synth::generate_sweep(SAMPLE_RATE, DURATION),
                    "pluck" => synth::generate_pluck(SAMPLE_RATE, DURATION, 440.0),
                    other => panic!("unknown synthetic signal: {other}"),
                };
                let path = dir
                    .join(format!("{kind}.wav"))
                    .to_str()
                    .unwrap()
                    .to_string();
                wav_io::write_wav(&path, SAMPLE_RATE, &synth::to_stereo(&mono))
                    .unwrap_or_else(|e| panic!("cannot write synthetic input '{path}': {e}"));
                path
            }
            Input::Clip(stem) => format!("{CORPUS_DIR}/{stem}.wav"),
        }
    }
}

/// Run the CLI's `process` over `input` with `params` and compare the result against the
/// stored golden, or overwrite that golden when `UPDATE_GOLDENS` is set.
fn run_golden(processor: &str, variant: &str, params: &[&str], input: &Input) {
    let dir = tempfile::tempdir().unwrap();
    let input_path = input.path(dir.path());
    let output_path = dir.path().join("out.wav").to_str().unwrap().to_string();

    run_process(&ProcessArgs {
        input_path,
        output_path: output_path.clone(),
        processor_name: processor.to_string(),
        params: params.iter().map(|p| p.to_string()).collect(),
    })
    .unwrap_or_else(|e| panic!("process {processor} failed: {e}"));

    let slug = input.slug();
    let path = format!("{GOLDEN_DIR}/{processor}_{variant}_{slug}.wav");
    let label = format!("{processor}_{variant}+{slug}");

    if std::env::var("UPDATE_GOLDENS").is_ok() {
        std::fs::copy(&output_path, &path)
            .unwrap_or_else(|e| panic!("failed to write golden {label}: {e}"));
        return;
    }

    let (_, output) = wav_io::read_wav(&output_path).unwrap();
    compare_golden(&path, &output, &label);
}

/// Declare one `#[test]` per case.
///
/// One test per case rather than a loop over the corpus, so a failure names the exact
/// clip that drifted and can be re-run on its own while you listen to it.
macro_rules! golden_cases {
    ($($name:ident: $proc:literal, $variant:literal, [$($param:literal),*] over $input:expr;)*) => {
        $(
            #[test]
            fn $name() {
                run_golden($proc, $variant, &[$($param),*], &$input);
            }
        )*
    };
}

// -- Default parameters --
//
// Gain at 0 dB is an identity, so one synthetic input is enough to guard the
// read/process/write chain; the filter and effect defaults are not identities.

golden_cases! {
    golden_gain_default_pluck: "gain", "default", [] over Input::Synthetic("pluck");
    golden_gain_default_mandolin_single_note_soft: "gain", "default", []
        over Input::Clip("mandolin_single_note_soft");
    golden_filter_default_impulse: "filter", "default", [] over Input::Synthetic("impulse");
    golden_filter_default_sweep: "filter", "default", [] over Input::Synthetic("sweep");
    golden_filter_default_pluck: "filter", "default", [] over Input::Synthetic("pluck");
    golden_filter_default_octave_mandolin_fast_run: "filter", "default", []
        over Input::Clip("octave_mandolin_fast_run");
    golden_asperitas_default_pluck: "asperitas", "default", [] over Input::Synthetic("pluck");
}

// -- Non-default parameters --
//
// The gains include a boost that pushes a loud clip past full scale, which float goldens
// keep unclamped. The low cutoffs expose the filter's slope and its decaying impulse tail.

golden_cases! {
    golden_gain_cut12_pluck: "gain", "cut12", ["gain_db=-12"] over Input::Synthetic("pluck");
    golden_gain_boost6_sweep: "gain", "boost6", ["gain_db=6"] over Input::Synthetic("sweep");
    golden_gain_boost12_octave_mandolin_single_note_hard: "gain", "boost12", ["gain_db=12"]
        over Input::Clip("octave_mandolin_single_note_hard");

    golden_filter_cutoff500_impulse: "filter", "cutoff500", ["cutoff_hz=500"]
        over Input::Synthetic("impulse");
    golden_filter_cutoff500_sweep: "filter", "cutoff500", ["cutoff_hz=500"]
        over Input::Synthetic("sweep");
    golden_filter_cutoff3000_mandolin_chord: "filter", "cutoff3000", ["cutoff_hz=3000"]
        over Input::Clip("mandolin_chord");

    golden_asperitas_cutoff800_cut6_impulse: "asperitas", "cutoff800_cut6",
        ["cutoff_hz=800", "gain_db=-6"] over Input::Synthetic("impulse");
    golden_asperitas_cutoff2000_boost6_mandolin_fast_run: "asperitas", "cutoff2000_boost6",
        ["cutoff_hz=2000", "gain_db=6"] over Input::Clip("mandolin_fast_run");
}

// -- Golden comparison helper --

fn compare_golden(path: &str, expected: &[Frame], label: &str) {
    if !std::path::Path::new(path).exists() {
        panic!(
            "golden file not found: {path}\n\
             Run `UPDATE_GOLDENS=1 cargo test -p asperitas-cli` to generate it."
        );
    }

    let (spec, actual) = wav_io::read_wav(path)
        .unwrap_or_else(|e| panic!("cannot read golden {label} at {path}: {e}"));
    assert_eq!(
        (spec.channels, spec.bits_per_sample, spec.sample_format),
        (2, 32, hound::SampleFormat::Float),
        "golden {label}: must be 32-bit float stereo"
    );

    assert_eq!(
        actual.len(),
        expected.len(),
        "golden {label}: length mismatch (expected {} samples, got {})",
        expected.len(),
        actual.len()
    );

    let mut max_delta = 0.0f32;
    for (i, (exp, act)) in expected.iter().zip(actual.iter()).enumerate() {
        for ch in 0..2 {
            let delta = (exp[ch] - act[ch]).abs();
            if delta > max_delta {
                max_delta = delta;
            }
            let exp_val = exp[ch];
            let act_val = act[ch];
            assert!(
                delta < TOLERANCE,
                "golden {label}: sample [{i}] channel {ch} differs by {delta:.8} \
                 (expected {exp_val:.8}, got {act_val:.8}) (tolerance {TOLERANCE})"
            );
        }
    }

    if max_delta > 0.0 {
        eprintln!(
            "golden {label}: max sample delta = {max_delta:.2e} (within tolerance {TOLERANCE})"
        );
    }
}
